"The ceiling for the peaks between samples. −1 leaves room for the MP3 and AAC encoders, which add peaks of their own.": "O teto para os picos entre amostras. −1 deixa espaço para os codificadores MP3 e AAC, que somam picos próprios.",
"Also an MP3 at 320 kbps, beside the WAV and the FLAC.": "Também um MP3 a 320 kbps, ao lado do WAV e do FLAC.",
"also MP3": "também MP3",
"What is upscaled: the take, or any file made from it but an upscaled one.": "O que recebe upscale: o take, ou qualquer arquivo feito a partir dele, menos um que já recebeu upscale.",
"Mode": "Modo",
"how deep it redraws": "com que profundidade ele redesenha",
"Subtle — above 12 kHz": "Sutil — acima de 12 kHz",
"Normal — above 8 kHz": "Normal — acima de 8 kHz",
"High — above 6 kHz": "Alto — acima de 6 kHz",
"Extreme — above 4 kHz": "Extremo — acima de 4 kHz",
"How many versions to draw: they differ only by the noise, and each takes as long as the first. Two let you pick by ear.": "Quantas versões desenhar: diferem só pelo ruído, e cada uma leva tanto tempo quanto a primeira. Duas deixam você escolher de ouvido.",
"Variants": "Variantes",
"Keep the original below the cutoff": "Manter o original abaixo do corte",
"What is debuzzed: the take, or a file made from it that is neither debuzzed nor upscaled.": "O que perde o zumbido: o take, ou um arquivo feito a partir dele que não esteja sem zumbido nem com upscale.",
"Strength": "Força",
"How much of the frame ripple to divide out. Viktor's ear: 100 % thinned the opening, 80 % was right.": "Quanto da ondulação dos quadros dividir fora. O ouvido do Viktor: 100 % afinava a abertura, 80 % ficou certo.",
"Which file is measured: the take, or any file made from it.": "Qual arquivo é medido: o take, ou qualquer arquivo feito a partir dele.",
"Inspect": "Inspecionar",
"Where the sound sits: spectrogram, average spectrum, band energy. Lay another take over it to compare.": "Onde o som está: espectrograma, espectro médio, energia por banda. Sobreponha outro take para comparar.",
"Log": "Log",
"Linear": "Linear",
"Lays a second spectrum under this one, on the same scale: a file made from this take, or another take.": "Põe um segundo espectro sob este, na mesma escala: um arquivo feito a partir deste take, ou outro take.",
"Compare with": "Comparar com",
"Full screen: zoom and scroll (or double-click the picture). A click plays from there when this take is in the player.": "Tela cheia: zoom e rolagem (ou clique duas vezes na imagem). Um clique toca a partir dali quando este take está no player.",
"Full screen: zoom and scroll": "Tela cheia: zoom e rolagem",
"Whisper listens to this take on Forge and matches what it hears to your lyrics, minute by minute.": "O Whisper ouve este take no Forge e compara o que escuta com a sua letra, minuto a minuto.",
"What Whisper listens to": "O que o Whisper ouve",
"The take as it is, or a stem of it: on the vocal stem Whisper hears the words without the music": "O take como está, ou um stem dele: no stem de voz o Whisper ouve as palavras sem a música",
"Listen with Whisper": "Ouvir com o Whisper",
"Karaoke timing": "Tempo de karaokê",
"Time the lines": "Sincronizar as linhas",
"Made from this take": "Feito a partir deste take",
"Made from This Take": "Feito a partir Deste Take",
