"Export format": "Formato de exportação",
"FLAC: lossless, about half the size of WAV. WAV: for tools that take nothing else.": "FLAC: sem perdas, cerca de metade do tamanho do WAV. WAV: para ferramentas que não aceitam outra coisa.",
"Also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Também cada arquivo feito a partir de cada take (remasters, stems, upscales, arquivos sem zumbido), com o nome do take.",
