"The server log, in every room: click to unfold or fold": "O log do servidor, em cada sala: clique para desdobrar ou dobrar",
"The line to the studio: the round trip, the middle of the last five (every 20 s). Near: the studio answers at once.": "A linha até o estúdio: a ida e volta, a mediana das últimas cinco (a cada 20 s). Perto: o estúdio responde na hora.",
"Follow: the log keeps to its newest line as the engine writes. Off: it stays where you scrolled to read.": "Acompanhar: o log fica na linha mais nova enquanto o motor escreve. Desligado: ele fica onde você rolou para ler.",
