"Every workspace's takes in this column, whatever workspace is in hand (new takes still land in that one); the column's other filters still apply": "Os takes de todos os espaços nesta coluna, qualquer que seja o espaço em uso (os takes novos continuam indo para ele); os outros filtros da coluna continuam valendo",
