"How wide the adapter's change is: 16 for one voice or instrument, 32 for a style, 64 for many voices, 128 at most.": "Quão amplo é o efeito do adaptador: 16 para uma voz ou instrumento, 32 para um estilo, 64 para muitas vozes, 128 no máximo.",
"Whether the music half learns (the part that writes the song's tokens), and how hard its lesson pulls against the anchor: 0 leaves it as the base, a timbre only; raise it for diction and style. What counts is the anchor's share of it, not its size.": "Se a metade musical aprende (a parte que escreve os tokens da canção), e com que força a lição dela puxa contra a âncora: 0 a deixa como a base, só um timbre; aumente para dicção e estilo. O que conta é a parte da âncora nele, não o tamanho.",
"Pulls the music half back toward the base model, so it keeps what the set does not show. Read it as a share of the AR weight: a tenth lets it move, as much as the weight holds it near the base. Nothing at AR weight 0.": "Puxa a metade musical de volta para o modelo de base, para que guarde o que o conjunto não mostra. Leia como uma parte do peso AR: um décimo a deixa se mover, tanto quanto o peso a segura perto da base. Nada com peso AR 0.",
"The music half's learning rate as a share of the one above: the knob that makes it learn faster or slower (0.5: half as fast). It learns a small set by heart quickly.": "A taxa de aprendizado da metade musical como fração da de cima: o ajuste que a faz aprender mais rápido ou mais devagar (0.5: na metade da velocidade). Ela decora rápido um conjunto pequeno.",
