"As the studio made it (and the Refiner finished it), no DAW in between. The take in hand:": "Como o estúdio a fez (e o Lapidador a terminou), sem DAW no meio. O take em mãos:",
"Open a take, play one, or check one in the Librarian: its WAV, FLAC and MP3 come here.": "Abra um take, toque um ou marque um no Bibliotecário: o WAV, o FLAC e o MP3 dele aparecem aqui.",
