"(the mix, every stem, the score as notes, the sections as markers: Waveform 14, Bitwig, Studio One, Cubase); both also in a take’s menu → Download. Waveform: 14 or newer.": "(o mix, cada stem, a partitura como notas, as seções como marcadores: Waveform 14, Bitwig, Studio One, Cubase); os dois também no menu de um take → Baixar. Waveform: 14 ou mais recente.",
"Packing…": "Empacotando…",
"60 days of evaluation with every function, then a licence: $60 for personal use or a small business": "60 dias de avaliação com todas as funções, depois uma licença: US$ 60 para uso pessoal ou pequena empresa",
"Waveform Free 14 or newer: free, no track or export limits; it opens the studio's DAWproject (File > Import Other > Import a DAWproject file). Waveform 13 is not supported": "Waveform Free 14 ou mais recente: grátis, sem limite de faixas ou de exportação; abre o DAWproject do estúdio (File > Import Other > Import a DAWproject file). O Waveform 13 não é suportado",
"30 days without limits after signing up, then Essentials $99, Producer $199 or Studio $399 (bitwig.com, 03.10.2026); opens the studio's DAWproject: the mix, the stems, the score as notes, the sections as markers": "30 dias sem limites após o cadastro, depois Essentials US$ 99, Producer US$ 199 ou Studio US$ 399 (bitwig.com, 03.10.2026); abre o DAWproject do estúdio: o mix, os stems, a partitura como notas, as seções como marcadores",
"reaper.fm/download.php → the Linux x86_64 tarball → unpack it and run ./install-reaper.sh (it goes to /opt/REAPER)": "reaper.fm/download.php → o tarball Linux x86_64 → descompacte e rode ./install-reaper.sh (vai para /opt/REAPER)",
