"bitwig.com/download: the Ubuntu .deb (sudo apt install ./bitwig-studio-*.deb) or the Flatpak": "bitwig.com/download: o .deb para Ubuntu (sudo apt install ./bitwig-studio-*.deb) ou o Flatpak",
