"The studio's approved sets, as their author published them. Each comes in as a workspace of its own, locked against deletion: its takes as MP3 with their covers, titles and notes. Only what you ask for is downloaded.": "Os conjuntos aprovados do estúdio, como o autor os publicou. Cada um entra como um espaço próprio, travado contra exclusão: os takes em MP3 com capas, títulos e notas. Só o que você pedir é baixado.",
