"“{0}” is here already": "“{0}” já está aqui",
"Restoring brings back the copy published on Hugging Face: the takes it lacks come again, titles and notes return to the published ones, and what was added to it leaves the workspace (those takes stay in the library; its own sections stay). To keep yours as it is: Cancel, rename your workspace (the ⋯ beside its name, then Rename…), and Get again: the original comes in beside it under its own name.": "Restaurar traz de volta a cópia publicada no Hugging Face: os takes que faltam voltam, títulos e notas voltam aos publicados, e o que foi acrescentado sai do espaço (esses takes ficam na biblioteca; as seções próprias dele ficam). Para manter o seu como está: Cancelar, renomeie seu espaço (o ⋯ ao lado do nome, depois Renomear…), e Obter de novo: o original entra ao lado com o próprio nome.",
"Restore the original": "Restaurar o original",
