"Freeze…": "Congelar…",
"heard, never changed": "ouvidos, nunca mudados",
"Freeze “{0}”?": "Congelar “{0}”?",
"Its takes stay as they are: they are heard and read, never changed, moved or thrown away, and they leave All Workspaces and the search (a take also in a workspace that is not frozen stays there). The workspace greys out; Unfreeze in its ⋯ menu brings everything back.": "Os takes ficam como estão: são ouvidos e lidos, nunca mudados, movidos ou jogados fora, e saem de Todos os espaços e da busca (um take também num espaço não congelado fica lá). O espaço fica cinza; Descongelar no menu ⋯ dele traz tudo de volta.",
"Freeze": "Congelar",
"Frozen: “{0}”": "Congelado: “{0}”",
"Unfrozen: “{0}”": "Descongelado: “{0}”",
"Frozen with its workspace": "Congelado com o espaço",
"unfreeze it to act on the take": "descongele-o para mexer no take",
"{#0} take frozen with its workspace: unfreeze it first": {"one": "{#0} take congelado com o espaço: descongele-o primeiro", "other": "{#0} takes congelados com o espaço: descongele-o primeiro"},
"{#0} takes frozen with their workspace: unfreeze it first": {"one": "{#0} take congelado com o espaço: descongele-o primeiro", "other": "{#0} takes congelados com o espaço: descongele-o primeiro"},
"“{0}” is frozen: unfreeze it first (⋯ beside its name)": "“{0}” está congelado: descongele-o primeiro (⋯ ao lado do nome)",
"frozen with its workspace: unfreeze it first": "congelado com o espaço: descongele-o primeiro",
"With the studio's LoRA": "Com o LoRA do estúdio",
"no adapter": "nenhum adaptador",
"{0}: its curve through the song": "{0}: sua curva pela canção",
"How its strength runs through the song: flat, an arch, or drawn by hand": "Como a força corre pela canção: plana, em arco, ou desenhada à mão",
"Flat": "Plana",
"Arch": "Arco",
"Draw": "Desenhar",
"The key the bed's chords are in; taken from the style when it names one («Bb major», «F#m»)": "A tonalidade dos acordes da base; tirada do estilo quando ele a nomeia («Bb major», «F#m»)",
"The meter of the bed's bars: 4/4, 3/4, 6/8 or 2/4": "O compasso da base: 4/4, 3/4, 6/8 ou 2/4",
"The bed's tempo, 40 to 240 BPM; taken from the style when it names one («96 BPM»)": "O andamento da base, de 40 a 240 BPM; tirado do estilo quando ele o nomeia («96 BPM»)",
"A chord bed: a score written at once from the key, the meter and the tempo here, a few bars of chords for every section of the lyrics, the Vocal voice resting and the instruments empty. In Full the model writes the melody and the arrangement over that harmony. Each press draws other progressions (one for the verses, one for the choruses, one for a bridge). After timoncool's YuE2-Studio (MIT) and gary4juce's yuey scaffold": "Uma base de acordes: uma partitura escrita de uma vez a partir da tonalidade, do compasso e do andamento daqui, alguns compassos de acordes para cada seção da letra, a voz Vocal em pausa e os instrumentos vazios. Em Full o modelo escreve por cima a melodia e o arranjo sobre essa harmonia. Cada clique tira outras progressões (uma para as estrofes, uma para os refrões, uma para uma ponte). A partir do YuE2-Studio de timoncool (MIT) e do yuey scaffold de gary4juce",
"A bed of {0} bars in {1}: verse {2} · chorus {3} · bridge {4}": "Uma base de {0} compassos em {1}: estrofe {2} · refrão {3} · ponte {4}",
"Replace the score in the form with a chord bed?": "Substituir a partitura do formulário por uma base de acordes?",
"Chord bed written: {0} bars; the planning mode is Full": "Base de acordes escrita: {0} compassos; o modo de planeamento é Full",
"Chord bed": "Base de acordes",
"Write a bed": "Escrever uma base",
"Meter": "Compasso",
"Tempo (BPM)": "Andamento (BPM)",
"The score's Vocal line an octave down (▼) or up (▲), once, in the score in the form (Full only): for a voice that sits lower or higher than the score asks. The model sings where the line goes: measured 21.10.2026, an octave down sang 9–10 semitones lower.": "A linha Vocal da partitura uma oitava abaixo (▼) ou acima (▲), uma vez, na partitura do formulário (só Full): para uma voz que fica mais grave ou mais aguda do que a partitura pede. O modelo canta onde a linha vai: medido em 21.10.2026, uma oitava abaixo cantou 9–10 semitons mais grave.",
"The Vocal line an octave down": "A linha Vocal uma oitava abaixo",
"The Vocal line an octave up": "A linha Vocal uma oitava acima",
"Volume. Past 100 % a boost up to 150 % for a quiet take: the slider stops at 100 % first; let go and drag again to go past it": "Volume. Acima de 100 %, um reforço até 150 % para um take baixo: o controlo para primeiro nos 100 %; solta e arrasta de novo para passar",
"IRAE merge": "Fusão IRAE",
"IRA with monsterovich's Epic Trailer adapter folded in on top, at three strengths (music / sound): IRAE 0.32 / 0.32, the fullest by ear; IRAEv2 0.28 / 0.24, cleaner; IRAEv3 0.5 / 0.375, its author's own, at its best on instrumentals. Ruach Studio's merges, from goldhub/YuE2-3B-Ruach_Studio-IRA-Merge (CC BY-NC 4.0). Compute chooses them beside m-a-p's backbones; do not add Instrumental, Real Audio or Epic Trailer on top": "IRA com o adaptador Epic Trailer de monsterovich incorporado por cima, em três intensidades (música / som): IRAE 0.32 / 0.32, a mais cheia ao ouvido; IRAEv2 0.28 / 0.24, mais limpa; IRAEv3 0.5 / 0.375, as do próprio autor, no seu melhor em instrumentais. Fusões do Ruach Studio, de goldhub/YuE2-3B-Ruach_Studio-IRA-Merge (CC BY-NC 4.0). Processamento escolhe-as junto aos modelos base da m-a-p; não acrescentes Instrumental, Real Audio nem Epic Trailer por cima",
"IRA with monsterovich's Epic Trailer adapter folded in on top, at three strengths (music / sound): IRAE 0.32 / 0.32, the fullest by ear; IRAEv2 0.28 / 0.24, cleaner; IRAEv3 0.5 / 0.375, its author's own, at its best on instrumentals. Ruach Studio's merges, from goldhub/YuE2-3B-Ruach_Studio-IRA-Merge (CC BY-NC 4.0). Compute chooses them beside m-a-p's backbones; do not add Instrumental, Real Audio or Epic Trailer on top. IRAE-IR (0.4 / 0.6) and IRAE-IRv2 (0.32 / 0.6) carry monsterovich's Industrial Rock as well: experimental, highly unstable on lyrics, mostly for rock instrumentals; nor Industrial Rock on them": "IRA com o adaptador Epic Trailer de monsterovich incorporado por cima, em três intensidades (música / som): IRAE 0.32 / 0.32, a mais cheia ao ouvido; IRAEv2 0.28 / 0.24, mais limpa; IRAEv3 0.5 / 0.375, as do próprio autor, no seu melhor em instrumentais. Fusões do Ruach Studio, de goldhub/YuE2-3B-Ruach_Studio-IRA-Merge (CC BY-NC 4.0). Processamento escolhe-as junto aos modelos base da m-a-p; não acrescentes Instrumental, Real Audio nem Epic Trailer por cima. IRAE-IR (0.4 / 0.6) e IRAE-IRv2 (0.32 / 0.6) trazem também o Industrial Rock de monsterovich: experimentais, muito instáveis na letra, sobretudo para instrumentais de rock; nem Industrial Rock por cima",
"the IRAE merge {0}": "a fusão IRAE {0}",
