"The studio runs on the Intel Arc (SYCL, beta): these cards are free for training and the lab's jobs.": "O estúdio roda na Intel Arc (SYCL, beta): estas placas ficam livres para o treino e as tarefas do laboratório.",
"the studio, on SYCL": "o estúdio, em SYCL",
"Sections": "Seções",
"The adapter sounds in the ticked sections and rests in the others, with a short ramp at each border.": "O adaptador soa nas seções marcadas e se cala nas outras, com uma rampa curta em cada fronteira.",
