"Look up on Civitai": "Consultar no Civitai",
"Each adapter not yet known looked up on civitai.com by its SHA-256 alone: its name, its base model and its trigger words kept beside it (NAME.civitai.info), with its first picture rated safe when it has none": "Cada adaptador ainda desconhecido consultado no civitai.com só pelo SHA-256: o nome, o modelo base e as palavras-gatilho guardados ao lado dele (NAME.civitai.info), com a primeira imagem classificada como segura quando ele não tem nenhuma",
