"No adapters for {0} here yet.": "Nenhum adaptador para {0} aqui ainda.",
"Put .safetensors files into the studio's artwork/loras/{0}/ folder: any folders inside it become groups here; a picture beside a file with its name (NAME.jpg, NAME.png, NAME.preview.png) shows on its card.": "Ponha arquivos .safetensors na pasta artwork/loras/{0}/ do estúdio: as pastas dentro dela viram grupos aqui; uma imagem ao lado de um arquivo com o nome dele (NAME.jpg, NAME.png, NAME.preview.png) aparece no cartão.",
"On Civitai, pick adapters by their base model ({0}), download the .safetensors and put it there; Look up on Civitai then fills in its name and its trigger words.": "No Civitai, escolha adaptadores pelo modelo base ({0}), baixe o .safetensors e ponha lá; Consultar no Civitai depois preenche o nome e as palavras-gatilho.",
