"All the sound strengths together. By ear (05.10.2026): two adapters at sound 1.0 each, 2.0 together, brought a heavy bass; 0.55 together sounded right. Green to 1, amber to 1.5, red past it. Drag it to move them all at once, each in proportion.": "Todas as forças de som juntas. De ouvido (05.10.2026): dois adaptadores no som 1.0 cada, 2.0 juntos, trouxeram um grave pesado; 0.55 juntos soou certo. Verde até 1, âmbar até 1.5, vermelho além. Arraste para mover todos de uma vez, cada um na proporção.",
