"How often should the studio look for a new release?": "Com que frequência o estúdio deve procurar uma versão nova?",
"It asks GitHub for the list of its releases, nothing more. When one is out you are asked first; Engine → Updates can update by itself instead, and look whenever you ask.": "Ele pede ao GitHub a lista das versões, nada mais. Quando sai uma, você é perguntado antes; Motor → Atualizações pode atualizar sozinho em vez disso, e procurar quando você pedir.",
"Every week": "Toda semana",
"Every day": "Todo dia",
"Every month": "Todo mês",
