"How often the studio asks GitHub for the list of its releases, nothing more. Never: only when you press Check now": "Com que frequência o estúdio pede ao GitHub a lista das suas versões, nada mais. Nunca: só quando você aperta Verificar agora",
"Ask: a window says what is new, and you choose. Update by itself: when nothing runs, the studio fetches it, builds it and restarts (only where it is a clone of its repository)": "Perguntar: uma janela diz o que há de novo, e você escolhe. Atualizar sozinho: quando nada roda, o estúdio a baixa, compila e reinicia (só onde ele é um clone do seu repositório)",
