"The engine restarts…": "O motor está reiniciando…",
"The studio does not run as a service here (Pinokio, or ./start.sh by hand): stop it and start it again there, and the engine lists what came.": "O estúdio não roda aqui como serviço (Pinokio, ou ./start.sh à mão): pare-o e inicie de novo lá, e o motor lista o que chegou.",
