"For a card of 16 GB (below 20 GB its text encoder reads the prompt on the processor: 17 GB of RAM); half a minute a picture on a 3090; less when some of it is here": "Para uma placa de 16 GB (abaixo de 20 GB o codificador de texto lê o prompt no processador: 17 GB de RAM); meio minuto por imagem numa 3090; menos quando parte dele já está aqui",
