"Not in OpenRouter's list: check the name": "Não está na lista do OpenRouter: confira o nome",
"Any model of openrouter.ai/models, written provider/model; the field offers the whole list as you type, each with its price per million tokens in and out. The quick picks fill it in.": "Qualquer modelo de openrouter.ai/models, escrito provedor/modelo; o campo oferece a lista toda enquanto você digita, cada um com o preço por milhão de tokens de entrada e saída. As escolhas rápidas o preenchem.",
