"Your draft is ready. Review and edit it, then apply what you like.": "Seu rascunho está pronto. Revise e edite, depois aplique o que gostar.",
"Export all": "Exportar tudo",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, in one file (a backup)": "Exportar tudo: cada documento do Escritor, com suas versões, os takes feitos a partir dele e sua lixeira, num arquivo (um backup)",
"Import a backup": "Importar um backup",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy. Nothing here is written over": "Importar um backup do Escritor: o que falta aqui entra; o que é igual fica como está; um documento que difere do homônimo daqui entra ao lado dele como cópia. Nada aqui é sobrescrito",
