"not a Writer backup (a file this room exported)": "não é um backup do Escritor (um arquivo que esta sala exportou)",
"Writer backup {0}: {1} new, {2} already here, {3} beside their namesakes as copies, {4} into the trash": "Backup do Escritor {0}: {1} novos, {2} já aqui, {3} ao lado dos homônimos como cópias, {4} para a lixeira",
"Not imported: {0}": "Não importado: {0}",
"Wipe out the art's trash": "Esvaziar a lixeira das artes",
