"Delete for good: {0} ({#1} MB).": "Apagar de vez: {0} ({#1} MB).",
"This cannot be undone.\n\nThe covers of a frozen workspace's takes stay.": "Isto não pode ser desfeito.\n\nAs capas dos takes de um espaço congelado ficam.",
