"taken off {0}": "tirada de {0}",
"{0} · seed {#1}": "{0} · semente {#1}",
"{#0} in the art's trash": "{#0} na lixeira das artes",
"Filter": "Filtro",
"Filter: {#0} on, joined {1}": "Filtro: {#0} ativos, unidos por {1}",
"Filter the takes shown: tick what to look for, and whether a take needs all of it (AND), any of it (OR) or none of it (NOR)": "Filtrar os takes mostrados: marque o que procurar, e se um take precisa de tudo (AND), de qualquer um (OR) ou de nenhum (NOR)",
"Clear the choice": "Limpar a escolha",
"The choice": "A escolha",
"To the trash: it gives them back until it is emptied": "Para a lixeira: ela os devolve até ser esvaziada",
"With what is made from them: also every file made from each take (remasters, stems, upscales, debuzzed files), named after the take.": "Com o que foi feito a partir deles: também cada arquivo feito de cada take (remasters, stems, ampliações, arquivos sem zumbido), com o nome do take.",
"Export ZIP: made on Forge, then saved by the browser where you tell it": "Exportar ZIP: feito na Forge, depois salvo pelo navegador onde você indicar",
