"Find the sections by ear": "Achar as seções de ouvido",
"Find the sections by ear again": "Achar as seções de ouvido de novo",
"being heard now": "ouvindo agora",
"Whisper hears the words; about half a minute on a card": "O Whisper ouve as palavras; cerca de meio minuto numa placa",
"A mark of the score. Each section of the lyrics with its words: the take's menu, Find the sections by ear": "Uma marca da partitura. Cada seção da letra com suas palavras: o menu do take, Achar as seções de ouvido",
"Wait: Whisper is binding the lyrics to the wave; the words come here in a moment": "Aguarde: o Whisper está ligando a letra à onda; as palavras chegam aqui em instantes",
"Wait: binding the lyrics to the wave…": "Aguarde: ligando a letra à onda…",
"Archive": "Arquivo",
"{#0} tags and marks": {"one": "{#0} tag e marca", "other": "{#0} tags e marcas"},
"the official examples counted": "os exemplos oficiais contados",
"it goes onto the clipboard and, where you say, into the Style prompt; a name the Style holds already is marked; a lyrics tag goes onto the clipboard only": "vai para a área de transferência e, onde você disser, para o prompt de Estilo; um nome que o Estilo já tem é marcado; uma tag de letra vai só para a área de transferência",
"The clipboard did not take it": "A área de transferência não aceitou",
"Russian · conservative (Viktor's)": "Russo · conservador (do Viktor)",
"The Artist's log": "O log do Pintor",
"Transcribed {0} in {1}. Check the melody under Supply your own score, then write the new lyrics and style.": "{0} transcrito em {1}. Confira a melodia em Fornecer sua própria partitura, depois escreva a nova letra e o estilo.",
"1 take carries a score you can remix.": "1 take traz uma partitura que você pode remixar.",
"{#0} takes carry a score you can remix.": {"one": "{#0} take traz uma partitura que você pode remixar.", "other": "{#0} takes trazem uma partitura que você pode remixar."},
"Make a song in Full plan or Melody only mode first; Direct mode keeps no score.": "Faça antes uma canção no modo Plano completo ou Só melodia; o modo Direto não guarda partitura.",
"A reference is a PNG, JPEG or WebP picture": "Uma referência é uma imagem PNG, JPEG ou WebP",
"The picture could not be read": "A imagem não pôde ser lida",
"Pick a take on the right first": "Escolha antes um take à direita",
"The prompt its artwork was drawn from": "O prompt de onde a arte dele foi desenhada",
"A prompt from its title and style: say more of what you see": "Um prompt a partir do título e do estilo: diga mais do que você vê",
"Put the take's prompt in place of the one written here?": "Pôr o prompt do take no lugar do que está escrito aqui?",
"What is written now goes; each run below keeps its own prompt.": "O que está escrito agora sai; cada execução abaixo guarda o próprio prompt.",
"Put it in": "Pôr",
"Pick a take with a cover on the right first": "Escolha antes um take com capa à direita",
"Back among the runs": "De volta às execuções",
"The upscaler": "O ampliador",
"In the trash: the studio's trash/artist/ keeps it; the library's Trash brings it back": "Na lixeira: o trash/artist/ do estúdio a guarda; a Lixeira da biblioteca a traz de volta",
