"✦ Suggest": "✦ Sugerir",
"Style suggestions: the Writer's model reads the Style, the Title and the lyrics' first lines and offers short tags this song has not got yet; a click on one puts it in (before the BPM at its end)": "Sugestões de estilo: o modelo do Escritor lê o Estilo, o Título e os primeiros versos da letra e oferece tags curtas que esta canção ainda não tem; um clique numa a insere (antes do BPM no fim)",
"Other suggestions": "Outras sugestões",
"Tighten these lyrics": "Enxugar esta letra",
