"Its strength over the steps: keyframes of a multiplier at a share of the steps, as ComfyUI's LoRA hooks. «0%:1, 50%:1, 60%:0» keeps it whole for half the steps and lets it go by 60 %; «0%:0, 30%:1» brings it in after the start. Between keyframes the multiplier runs straight; two at one share make a step.": "A força ao longo dos passos: quadros-chave de um multiplicador numa fração dos passos, como os hooks de LoRA do ComfyUI. «0%:1, 50%:1, 60%:0» o mantém inteiro na metade dos passos e o solta até 60 %; «0%:0, 30%:1» o faz entrar depois do início. Entre quadros-chave o multiplicador segue em linha reta; dois na mesma fração fazem um degrau.",
"Its strength over the steps": "A força ao longo dos passos",
