"Click: a point · drag: move it · right-click: away · ↑ ↓ the point a step · the pitch wheel too": "Clique: um ponto · arrastar: movê-lo · clique direito: tirar · ↑ ↓ o ponto um passo · a roda de pitch também",
"Bars {0}–{1} picked: ⇅ Transpose in the head": "Compassos {0}–{1} escolhidos: ⇅ Transpor no topo",
