"The keys back on the score's notes": "As teclas de volta às notas da partitura",
"The tempo the roll plays at: − and + by four, the wheel over it by one, a double click the score's own. A score in free tempo has none (YuE2 sings it rubato), so the roll takes the last one set here": "O andamento em que o roll toca: − e + de quatro em quatro, a roda sobre ele de um em um, um clique duplo o da própria partitura. Uma partitura em andamento livre não tem (o YuE2 canta rubato), então o roll pega o último definido aqui",
"Drag: more paper or more roll · a double click: as at first": "Arraste: mais papel ou mais roll · clique duplo: como no início",
"A MIDI keyboard: its pitch wheel runs the cursor through time, its modulation wheel sets a new note's length": "Um teclado MIDI: a roda de pitch move o cursor no tempo, a roda de modulação define a duração de uma nota nova",
"{0} BPM · free tempo": "{0} BPM · andamento livre",
"{0} BPM": "{0} BPM",
"To the start": "Para o início",
"A MIDI keyboard plays the piano roll; a controller's control port (an M-Audio Oxygen's DAW port in its Mackie preset, or any Mackie Control) runs the transport: the roll's, the DAW's in sight, else the player's. Early support: made to the Mackie Control protocol and tried through the browser's MIDI, not yet on every device.": "Um teclado MIDI toca no piano roll; a porta de controle de um controlador (a porta DAW de um M-Audio Oxygen no preset Mackie, ou qualquer Mackie Control) conduz o transporte: o do roll, o do DAW à vista, senão o do player. Suporte inicial: feito sobre o protocolo Mackie Control e testado pelo MIDI do navegador, ainda não em todo aparelho.",
"Listen to MIDI": "Ouvir MIDI",
"Stop listening to MIDI": "Parar de ouvir MIDI",
"No MIDI port": "Nenhuma porta MIDI",
"keys: they play the piano roll": "teclas: tocam no piano roll",
"control: {0}": "controle: {0}",
"left alone: no script speaks its language": "deixada de lado: nenhum script fala a língua dela",
"A plugin may bring a script for its own controller: plugin.json, \"midi\" (PLUGINS.md, «MIDI scripts»).": "Um plugin pode trazer um script para o próprio controlador: plugin.json, \"midi\" (PLUGINS.md, «MIDI scripts»).",
"A plugin's MIDI script did not load:": "O script MIDI de um plugin não carregou:",
"The keys' guide": "Guia das teclas",
