"Right-click or Delete: away": "Clique direito ou Delete: tirar",
"Shift and keys together: a chord on the cursor's bar": "Shift e teclas juntas: um acorde no compasso do cursor",
"The computer's keys: A S D F G H J K L ; ' white, W E T Y U O P ] black · Z X an octave": "As teclas do computador: A S D F G H J K L ; ' brancas, W E T Y U O P ] pretas · Z X uma oitava",
"← → a semitone · ↑ ↓ a step · Tab: the other staff": "← → um semitom · ↑ ↓ um passo · Tab: a outra pauta",
"Wheel: time · Ctrl+wheel: closer · Space: play · F11: the whole screen": "Roda: tempo · Ctrl+roda: mais perto · Espaço: tocar · F11: tela cheia",
"The instruments did not load ({0}): the roll plays its own built voices until it is opened again": "Os instrumentos não carregaram ({0}): o roll toca com as próprias vozes embutidas até ser aberto de novo",
"The instruments are on their way…": "Os instrumentos estão chegando…",
"MIDI needs the studio opened as localhost or over https; this page is {0}. From another computer: ssh -L {1} {2}, then {3}": "O navegador só dá MIDI a uma página em localhost ou por https; esta página é {0}. De outro computador: ssh -L {1} {2}, depois {3}",
"{0} control port(s) left to the controls": "portas de controle deixadas para os controles: {0}",
