"The keys an octave down": "As teclas uma oitava abaixo",
"The keys an octave up": "As teclas uma oitava acima",
"What is heard": "O que se ouve",
"Original": "Original",
"Edited": "Editado",
"From the cursor (Space); a click on the time at the left sets the cursor": "Do cursor (Espaço); um clique no tempo à esquerda põe o cursor",
"A MIDI keyboard of this computer: its keys play here; with Rec on, a key writes a note at the cursor and the cursor steps on": "Um teclado MIDI deste computador: suas teclas soam aqui; com Rec, uma tecla escreve uma nota no cursor e o cursor avança",
"Rec: a key (of the MIDI keyboard, the computer's keys or the keys below) writes a note of the grid's length at the cursor into the staff in hand, and the cursor steps on": "Rec: uma tecla (do teclado MIDI, do computador ou as desenhadas embaixo) escreve uma nota do tamanho da grade no cursor, na pauta em uso, e o cursor avança",
"Rec": "Rec",
"The roll into the score in the box: only the lines whose notes or chords changed are written anew, every other line stays as YuE2 wrote it": "O roll na partitura do campo: só as linhas cujas notas ou acordes mudaram são reescritas, todas as outras ficam como o YuE2 as escreveu",
"As YuE2 wrote it": "Como o YuE2 escreveu",
"As it stands now": "Como está agora",
"Click: a note · drag: move, its lower edge: longer · right-click or Delete: away · Shift and keys together: a chord on the cursor's bar · keys A S D F G H J K L ; ' and W E T Y U O P ]: a keyboard and a half, Z X an octave · ←→ a semitone, ↑↓ a step · Tab: the other staff · wheel: time, Ctrl+wheel: closer · F11: the whole screen": "Clique: uma nota · arrastar: mover, pela borda de baixo: mais longa · clique direito ou Delete: tirar · Shift e teclas juntas: um acorde no compasso do cursor · teclas A S D F G H J K L ; ' e W E T Y U O P ]: uma oitava e meia, Z X uma oitava · ←→ um semitom, ↑↓ um passo · Tab: a outra pauta · roda: o tempo, Ctrl+roda: mais perto · F11: a tela inteira",
"a chord: keep Shift and add keys": "um acorde: segure Shift e acrescente teclas",
"no chord YuE2 reads": "nenhum acorde que o YuE2 leia",
"let go of Shift to set it on the cursor's bar": "solte Shift para pô-lo no compasso do cursor",
"Chord {0} on bar {1}": "Acorde {0} no compasso {1}",
"The computer's keys from {0}": "As teclas do computador a partir de {0}",
