"One's own MIDI keyboard: the keys it reaches marked over the keyboards (they keep their size); ‹ › move the keys in sight an octave": "Seu próprio teclado MIDI: as teclas que ele alcança marcadas sobre os teclados (que mantêm o tamanho); ‹ › movem as teclas à vista uma oitava",
"Hear the score as YuE2 wrote it": "Ouvir a partitura como o YuE2 escreveu",
"Hear the score as it stands now": "Ouvir a partitura como está agora",
"The instruments' melody, as keys": "A melodia dos instrumentos, como teclas",
