"Piano roll": "Piano roll",
"The score in the box as a piano roll: both staves, Vocal and Ins, a note a click; written back into the score line by line, every untouched line as YuE2 wrote it": "A partitura do campo como piano roll: as duas pautas, Vocal e Ins, uma nota um clique; de volta à partitura linha a linha, cada linha intocada como o YuE2 a escreveu",
