"Both staves from the cursor, as plain tones at the score's tempo (Space); a click on the ruler sets the cursor": "As duas pautas a partir do cursor, como tons simples no andamento da partitura (Espaço); um clique na régua põe o cursor",
"The roll into the score in the box: only the lines whose notes changed are written anew, every other line stays as YuE2 wrote it": "O roll na partitura do campo: só as linhas cujas notas mudaram são reescritas, todas as outras ficam como o YuE2 as escreveu",
