"{0} takes no {1}": "{0} não recebe {1}",
"The take in hand: what every step starts from. A click opens the Takes, to pick another": "O take em uso: dele parte cada passo. Um clique abre os Takes, para escolher outro",
"The chain: its profile, Run the chain and On the workspace…; it runs the way drawn thick": "A cadeia: o seu perfil, Rodar a cadeia e No espaço…; ela roda o caminho desenhado em negrito",
"A track from anywhere (WAV, FLAC, MP3…) into the library as a take, marked imported; a way wired from here runs on each one imported next": "Uma faixa de qualquer lugar (WAV, FLAC, MP3…) para a biblioteca como take, marcada como importada; um caminho traçado daqui roda sozinho em cada importação seguinte",
"Every file made from this take, each under the one it came from: play, compare, rate, delete": "Cada arquivo feito a partir deste take, sob aquele de onde saiu: ouvir, comparar, avaliar, excluir",
"The spectrum of the take or of a file made from it: how loud each band is, over time": "O espectro do take ou de um arquivo feito dele: quão alta é cada banda no tempo",
"Faults measured in a file: clicks, clipping, the frame buzz, a hum": "Defeitos medidos num arquivo: cliques, clipping, o zumbido dos quadros, um hum",
"The lyrics held against what is sung (Whisper): which lines came and which did not": "A letra contra o que é cantado (Whisper): quais linhas vieram e quais não",
"The frame buzz of YuE2's sound out of the take: needed for every YuE2 take, off for a track from elsewhere": "O zumbido de quadro do som do YuE2 fora do take: necessário a cada take do YuE2, desligado para uma faixa de fora",
"UniverSR redraws the top of the spectrum above a cutoff, the original kept below it": "O UniverSR redesenha o topo do espectro acima de um corte, o original mantido abaixo",
"The file split into stems: four, six, eight, or the voice and the rest": "O arquivo separado em stems: quatro, seis, oito, ou a voz e o resto",
"The stems on lanes: levels, versions, buses and automation, then a mix": "Os stems em faixas: níveis, versões, buses e automação, depois uma mixagem",
"The Digital Gateway: tape, console and tube in numbers, on a file or a mix": "A Passagem digital: fita, console e válvula em números, num arquivo ou numa mixagem",
"The Debunker: a file or a set of stems balanced, compressed, toned and brought to a loudness": "O Debunker: um arquivo ou um conjunto de stems equilibrado, comprimido, tonalizado e levado a uma loudness",
"This machine's interfaces: the gateway's out and in, the monitor": "As interfaces desta máquina: a saída e a entrada da passagem, o monitor",
"The way: what the chain runs, step to step": "O caminho: o que a cadeia roda, passo a passo",
"Made: which file came from which": "Feito: qual arquivo saiu de qual",
"A step's own source, for a run from its window": "A fonte própria de um passo, para rodá-lo pela sua janela",
"Drag from a node's dot onto another: it joins the way after it; the nodes that can take it light up": "Arraste do ponto de um nó para outro: ele entra no caminho depois dele; acendem os nós que podem recebê-lo",
"Fold the legend": "Recolher a legenda",
"Unfold the legend": "Expandir a legenda",
"{0} was not on your way: it stands where its kind goes": "{0} não estava no seu caminho: entrou onde fica o seu tipo",
"The DAW's lanes take {0}'s newest: {1} of them": "As faixas do DAW pegam o mais novo de {0}: {1}",
"Nothing of {0} for the DAW's lanes yet: run it, or put it on the way": "Ainda nada de {0} para as faixas do DAW: rode-o ou ponha-o no caminho",
