"Not kept: {0}": "Não guardado: {0}",
"Who may open this studio?": "Quem pode abrir este estúdio?",
"The studio listens on port {0} of every network this computer is on. Whoever opens its page can do everything you can: make and delete songs, read your lyrics, run your graphics cards, fetch models with your keys.": "O estúdio escuta na porta {0} de cada rede em que este computador está. Quem abrir a página dele pode fazer tudo o que você faz: criar e apagar músicas, ler as suas letras, rodar as suas placas de vídeo, baixar modelos com as suas chaves.",
"At home behind your router, private networks are what you want: your laptop and phone reach the studio, the internet does not.": "Em casa, atrás do seu roteador, as redes privadas são o que você quer: o notebook e o celular chegam ao estúdio, a internet não.",
"On a public Wi-Fi (a café, a hotel, a train) or on a laptop without a firewall, everyone on that network counts as a private network too: choose This computer only, or list your own networks.": "Num Wi-Fi público (um café, um hotel, um trem) ou num notebook sem firewall, todos naquela rede contam também como rede privada: escolha «Só este computador» ou liste as suas próprias redes.",
"Engine → Security changes it any time. The internet at large is never let in, unless the studio is started with RUACH_ALLOW_PUBLIC=1.": "Motor → Segurança muda isso quando quiser. A internet em geral nunca entra, a menos que o estúdio seja iniciado com RUACH_ALLOW_PUBLIC=1.",
"My decision is a conscious one": "Minha decisão é consciente",
"Batch": "Lote",
"How many pictures in one go: each the next seed (the seed, the seed + 1, …), in every shape picked": "Quantas imagens de uma vez: cada uma a semente seguinte (a semente, a semente + 1, …), em cada formato escolhido",
"Delete the saved style picked": "Excluir o estilo salvo escolhido",
"Keep the list open": "Manter a lista aberta",
"Play this song": "Tocar esta canção",
"My songs": "Minhas músicas",
"“{0}” takes no new takes (a 💎 set, its section or a frozen workspace). Where do the new takes land?": "«{0}» não aceita novos takes (um conjunto 💎, a sua secção ou um espaço congelado). Onde caem os novos takes?",
"Nothing sent: the Librarian (Forge's lab) does not answer, so a new take would land in no workspace": "Nada enviado: o Bibliotecário (o laboratório da Forge) não responde, então um novo take não cairia em nenhum espaço",
"Nothing sent: the library is not on this page to say where the new takes land": "Nada enviado: a biblioteca não está nesta página para dizer onde caem os novos takes",
