"The chain up to this node and no further, with the chain's own settings: a node bypassed on the way is skipped, this one runs": "A cadeia até este nó e não além, com as próprias configurações: um nó contornado no caminho é pulado, este é executado",
"The chain runs past this node: its own check in the chain's row, turned off or on": "A cadeia passa ao lado deste nó: a própria caixa dele na linha da cadeia, marcada ou não",
