"the lab reaches the sound devices through sg audio: its service started before the audio group was given": "o laboratório chega aos dispositivos de som por sg audio: o serviço dele começou antes de o grupo audio ser dado",
"The interface the gateway plays a take out through, to the gear": "A interface pela qual a passagem manda o take ao equipamento",
