"A 1 kHz tone at −20 dBFS out through the output and back from the input: did it come back, its gain, the noise before it, its THD": "Um tom de 1 kHz a −20 dBFS sai pela saída e volta pela entrada: se voltou, o ganho, o ruído antes, o THD",
"Loop test": "Teste de loop",
"Choose the output and the input first": "Escolha primeiro a saída e a entrada",
"A 1 kHz tone at −20 dBFS plays through {0} for two seconds. Turn the monitors down if they are on.": "Um tom de 1 kHz a −20 dBFS vai tocar por {0} por dois segundos. Abaixe os monitores se estiverem ligados.",
