"The Creator's versions": "Versões do Criador",
"Every Generate keeps its title's words here, apart from the takes: a take deleted never takes them along.": "Cada Generate guarda aqui as palavras do seu título, à parte dos takes: um take apagado nunca as leva consigo.",
"Smaller": "Menor",
"Larger": "Maior",
