"VAE for the songs to come: {0}": "VAE para as próximas músicas: {0}",
"built in": "embutidos",
"Find it in the tree below": "Encontrá-lo na árvore abaixo",
"Close (Esc): back to the box, the match selected": "Fechar (Esc): de volta à caixa, com a ocorrência selecionada",
"Back to the last quarter-minute mark (0:15, 0:30…). The ← key: to the last 5 s mark": "Voltar à última marca de quarto de minuto (0:15, 0:30…). A tecla ←: à última marca de 5 s",
"Same as the text": "Igual ao texto",
"Up to three parts of the frame, each with words of its own: at every step the painter is asked once more for each region, with the prompt and the region's words, and the answers are blended by soft-edged boxes (Latent Couple's way). Each region costs a whole pass more a step. Qwen-Image 2512": "Até três partes do quadro, cada uma com as suas próprias palavras: a cada passo o pintor é consultado de novo para cada região, com o prompt e as palavras da região, e as respostas são misturadas por caixas de bordas suaves (à maneira do Latent Couple). Cada região custa uma passada inteira a mais por passo. Qwen-Image 2512",
"The score written in {0} (it came as {1}): the same notes, spelled as the engine sings them": "A partitura escrita em {0} (veio como {1}): as mesmas notas, escritas como o motor as canta",
"Export all: every document of the Writer, with its versions, the takes made from it and its trash, and the Creator's versions of every title, in one file (a backup)": "Exportar tudo: cada documento do Escritor, com suas versões, os takes feitos a partir dele e sua lixeira, e as versões do Criador de cada título, num só arquivo (um backup)",
"Import a Writer backup: what is missing here comes in; the same is left alone; a document that differs from its namesake here comes in beside it as a copy; a title of the Creator's versions here gains the versions it lacks. Nothing here is written over": "Importar um backup do Escritor: o que falta aqui entra; o igual fica como está; um documento que difere do seu homônimo daqui entra ao lado como cópia; um título das versões do Criador ganha as versões que lhe faltam. Nada aqui é sobrescrito",
"Writer backup: {0} documents and {1} in the trash, the Creator's versions of {2} titles, into {3}": "Backup do Escritor: {0} documentos e {1} na lixeira, as versões do Criador de {2} títulos, em {3}",
"the Creator's versions: {0} new, {1} titles new": "versões do Criador: {0} novas, {1} títulos novos",
"Refiner Room": "Sala do Lapidador",
"How the Refiner room opens: its steps as a list, or its nodes on a canvas. The List and Canvas button in the room's head switches at any time.": "Como abre a sala do Lapidador: os passos em lista ou os nós numa tela. O botão Lista / Tela no topo da sala alterna a qualquer momento.",
"The Refiner is a canvas of nodes: every step a node, wired the way the work flows and numbered by it; a click or its number's key (1…9, 0) opens one.": "O Lapidador é uma tela de nós: cada passo um nó, ligados como o trabalho flui e numerados por ele; um clique ou a tecla do seu número (1…9, 0) abre um.",
"The Refiner opens": "O Lapidador abre",
"As it was left": "Como foi deixado",
