"Always the list": "Sempre em lista",
"The steps one under another, as the Refiner began.": "Os passos um abaixo do outro, como o Lapidador começou.",
"Always the canvas": "Sempre em tela",
"The nodes and their wires; a click opens one; nothing to scroll at 1080p.": "Os nós e seus fios; um clique abre um; nada a rolar em 1080p.",
