"Double-click to add a band there; drag a band's point (Shift finer); the wheel over it sets its width; a right-click takes it away. Behind the curve: the strip's own sound as it plays": "Duplo clique adiciona ali uma banda; arraste o ponto de uma banda (Shift mais fino); a roda sobre ele define sua largura; um clique direito a remove. Atrás da curva: o próprio som da faixa enquanto toca",
"Each echo darker than the one before, above this": "Cada eco mais escuro que o anterior, acima disto",
"Everything set here is heard as it is set and mixed on Forge as it is heard: the same EQ, compressor, pan, room and delay. Drag along a wave to silence a stretch, right-click it to give it back, click to play from there.": "Tudo o que se ajusta aqui se ouve ao ajustar e é mixado no Forge como se ouve: o mesmo EQ, compressor, pan, sala e delay. Arraste ao longo de uma onda para silenciar um trecho, clique direito para devolvê-lo, clique para tocar dali.",
