"Without a note": "Sem nota",
// HERESY 1734: why the wave's section edits are greyed
"Sections and lyrics on the wave are off (the player's switch)": "As seções e a letra na onda estão desligadas (o interruptor do player)",
"These are the score's marks: Find the sections by ear first (in this menu)": "São marcas da partitura: primeiro «Achar as seções de ouvido» (neste menu)",
