"No section under the pointer": "Nenhuma seção sob o ponteiro",
"The rest of a part sung anew: the pointer over the part itself": "O resto de uma parte cantada de novo: o ponteiro sobre a própria parte",
"No words here, an instrumental part: the pointer over a sung section": "Aqui não há letra, é uma parte instrumental: o ponteiro sobre uma seção cantada",
"Whisper did not hear its first or last line clearly (marked ?)": "O Whisper não ouviu com clareza a primeira ou a última linha dela (marcada ?)",
"Too short to cut": "Curto demais para cortar",
