"No adapters: the window is sung anew on the bare model": "Sem adaptadores: a janela é cantada de novo no modelo puro",
"Its wave over the window": "A onda dele na janela",
"Rise": "Subida",
"Fall": "Descida",
"Play the take first: its window is laid on its wave": "Toque o take primeiro: a janela dele fica sobre a onda dele",
