// HERESY 1760: a strip's gate
"Gate": "Gate",
"Range": "Profundidade",
"Below it the gate closes, by its ratio": "Abaixo dele o gate fecha, pela sua razão",
"How much it lowers what is under the threshold: 4:1 takes 10 dB under it down 40": "Quanto ele abaixa o que fica sob o limiar: 4:1 abaixa 40 dB o que está 10 dB abaixo",
"The most it lowers anything: the floor the bleed is left at": "O máximo que ele abaixa qualquer coisa: o piso onde o vazamento fica",
"How fast it opens when the sound comes back": "Quão rápido ele abre quando o som volta",
"How fast it closes after the sound: longer, the tails kept": "Quão rápido ele fecha depois do som: mais longo, as caudas ficam",
"The gate: what it takes away between the phrases as it plays": "O gate: o que ele tira entre as frases enquanto toca",
"The gate's reduction as it plays": "A redução do gate enquanto toca",
"It listens to the strip itself, after its EQ: below the threshold the strip goes down by the ratio, never more than the range, so the bleed between the phrases falls away": "Ele ouve a própria faixa depois do seu EQ: sob o limiar a faixa desce pela razão, nunca mais que a profundidade, e o vazamento entre as frases some",
// HERESY 1762: the returns' pre-delay and cuts
"Pre-delay": "Pré-delay",
"The room comes in this much after the sound, on top of its own: the word clear before its room": "A sala entra este tanto depois do som, além do seu próprio atraso: a palavra clara antes que chegue a sua sala",
"Below this the room is cut: no mud under the voice; Off at 20 Hz": "Abaixo disto a sala é cortada: nada de lama sob a voz; desligado em 20 Hz",
"Above this the room is cut: a darker room, the sibilants out of it; Off at 20 kHz": "Acima disto a sala é cortada: uma sala mais escura, as sibilantes fora dela; desligado em 20 kHz",
"Below this the echoes are cut, all of them alike: no bass in them; Off at 20 Hz": "Abaixo disto os ecos são cortados, todos por igual: sem graves neles; desligado em 20 Hz",
"Above this the echoes are cut, all of them alike (the low-pass darkens each one more than the last); Off at 20 kHz": "Acima disto os ecos são cortados, todos por igual (o passa-baixa escurece cada um mais que o anterior); desligado em 20 kHz",
// HERESY 1763: the master's loudness range and PLR
"The loudness range since play, by EBU Tech 3342: how far the song's short-term loudness moves, its quietest 10 % and its loudest 5 % left out; the mix on Forge says its own": "A faixa de loudness desde o play, pela EBU Tech 3342: quanto a loudness de curto prazo da música se move, sem os seus 10 % mais baixos e os 5 % mais altos; a mix no Forge diz a sua",
"Peak to loudness: the true peak over the integrated loudness since play; the smaller, the more squashed the song": "Pico para loudness: o pico real acima da loudness integrada desde o play; quanto menor, mais esmagada a música",
// HERESY 1765: a run from elsewhere stopped on a broken score
"A run started elsewhere stopped on a broken score: {0}. Nothing was sung, nothing here changed": "Uma execução iniciada noutro lugar parou numa partitura quebrada: {0}. Nada foi cantado, nada mudou aqui",
// HERESY 1768: the decode ladder in the Creator
"Sound decode": "Decodificação do som",
"Whole song · standard": "Canção inteira · padrão",
"Ladder · experimental": "Escada · experimental",
"Experimental: what comes out differs from the standard decode. How the sound half turns the music codes into sound. Whole song, the standard (and the only way everywhere else in the Studio): one solve over the whole song, stable and predictable. Ladder: the song in even pieces of about 20 s, each solved hearing 2 s of the music past both its edges, the neighbours crossfaded over the 2 s round each joint (the best of the probes by Viktor's ear, 24.10.2026). On the same codes and seeds it comes out close to the whole-song decode, not the same, and further from it on a fine-tuned checkpoint; for now it takes the same time. A song under 20 s is one piece. Only the Creator's runs and their «Also render with» go this way; a section or a window sung anew, a new sound, a trim, an end or a fade-in in the player decode the standard way.": "Experimental: o que sai difere da decodificação padrão. Como a metade sonora transforma os códigos da música em som. Canção inteira, o padrão (e o único caminho em todo o resto do Studio): uma só resolução sobre a canção inteira, estável e previsível. Escada: a canção em pedaços iguais de cerca de 20 s, cada um resolvido ouvindo 2 s de música além das suas duas bordas, os vizinhos em crossfade nos 2 s em volta de cada junção (a melhor das provas ao ouvido do Viktor, 24.10.2026). Nos mesmos códigos e sementes sai perto da decodificação da canção inteira, não igual, e mais longe num checkpoint afinado; por enquanto leva o mesmo tempo. Uma canção com menos de 20 s é um só pedaço. Só as execuções do Criador e o seu «Renderizar também com» vão assim; uma secção ou uma janela cantadas de novo, um som novo, um corte, um fim ou uma entrada em fade no leitor decodificam-se do modo padrão.",
