"when its first minute is in and the rest will come in time": "quando chegar o primeiro minuto e o resto chegar a tempo",
"when the whole take is in": "quando chegar o take inteiro",
"On a slow line (a studio far away), a take can start before all of it has come: once its first minute is in and the rest will come before the playing reaches it; where it changes to the whole, it does so at a quiet moment. At home the whole comes within seconds, and it waits for it either way.": "Numa linha lenta (um estúdio longe), um take pode começar antes de chegar inteiro: assim que chega o primeiro minuto e o resto chegará antes de a reprodução lá chegar; onde muda para o inteiro, fá-lo num momento calmo. Em casa o inteiro chega em segundos, e espera-o de qualquer modo.",
